Object.assign(CONTENT.skills, {
  md:   { name: "…마다 · form", rule: "A noun takes 마다 directly: 아침마다, 나라마다, 사람마다. A verb goes through 때: -을/-ㄹ 때마다, 갈 때마다, 먹을 때마다. Nothing comes between the noun and 마다." },
  mdu:  { name: "…마다 · every, each, whenever", rule: "‘Every’ or ‘each’ with a noun (날마다, 집마다), ‘whenever’ with -을 때마다. It says the same thing holds each time, or that each one is different: 사람마다 달라요." },
  pp:   { name: "-을/-ㄹ 뻔하다 · form", rule: "-을 뻔하다 after a consonant, -ㄹ 뻔하다 after a vowel; a ㄹ stem adds nothing: 쏟을 뻔했어요, 마실 뻔했어요, 울 뻔했어요. ㄷ, ㅅ and ㅂ irregulars change first: 들을, 지을, 주울." },
  ppu:  { name: "-을/-ㄹ 뻔하다 · it nearly happened", rule: "Something almost happened and did not. It is nearly always in the past: 넘어질 뻔했어요. If it really happened, this is the wrong form." },
  voc10: { name: "Chapter 10 words · manners, and how a mistake feels", rule: "고개를 숙이다 is to bow the head, 말을 놓다 to drop polite speech, 자리를 양보하다 to give up one's seat. 당황하다 is to be flustered, 창피하다 and 민망하다 embarrassed, 황당하다 dumbfounded, 신기하다 fascinating." },
  col10: { name: "Gestures and reactions", rule: "고개를 숙이다, 두 손을 모으다, 볼을 맞대다, 자리를 양보하다, 코를 풀다, 말을 놓다, 머리를 쓰다듬다; 웃음이 나다, 손에 땀이 나다, 얼굴이 빨개지다, 가슴이 두근거리다." },
});
